import path from "node:path";

import { defineConfig } from "@playwright/test";

// SESSION_SECRET, with which the token tests read and forge session cookies:
// the repository root's .env, generated by scripts/secrets.sh. An explicit
// SESSION_SECRET in the environment wins (it is not loaded then).
// Playwright loads this config as CommonJS: no import.meta here.
if (!process.env.SESSION_SECRET) {
  const envFile = path.resolve(__dirname, "..", ".env");
  try {
    process.loadEnvFile(envFile);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    throw new Error(`Missing ${envFile}: run scripts/secrets.sh at the repository root`);
  }
}

/**
 * End-to-end tests (e2e/), against the whole stack already running: this
 * application on :3000 and Keycloak, both through the edge, Mailpit and the
 * storage service, seeded with the product catalog
 * (storage/scripts/seed-products.sh), which e2e/global-setup.ts checks
 * first. They register new accounts each run, and add products and reviews.
 *
 *   npm run e2e                       with Playwright's Chromium (npx playwright install chromium)
 *   E2E_CHANNEL=chrome npm run e2e    with the installed Google Chrome
 */
export default defineConfig({
  testDir: "e2e",
  // The stack is up and seeded, or nothing runs (e2e/global-setup.ts).
  globalSetup: "./e2e/global-setup.ts",
  // Each test is one person's journey, from registering on.
  timeout: 120_000,
  expect: { timeout: 10_000 },
  workers: 2,
  // A test that passes only on a second try is a flaky one: never retry.
  retries: 0,
  // In CI (.gitlab-ci.yml), a stray test.only fails the run, and results
  // are also written as JUnit XML for the merge request.
  forbidOnly: !!process.env.CI,
  reporter: process.env.CI
    ? [["list"], ["html", { open: "never" }], ["junit", { outputFile: "test-results/junit.xml" }]]
    : [["list"], ["html", { open: "never" }]],
  use: {
    baseURL: process.env.E2E_BASE_URL ?? "http://localhost:3000",
    channel: process.env.E2E_CHANNEL || undefined,
    viewport: { width: 1280, height: 900 },
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
  },
  projects: [
    { name: "journeys", testIgnore: /edge\.spec\.ts/ },
    // Its burst uses up the address's allowance at the edge (edge/), which
    // every test shares: so after the others.
    { name: "edge", testMatch: /edge\.spec\.ts/, dependencies: ["journeys"] },
  ],
});
